const input = $input.first().json;
const errors = [];

if (!input.article_id && input.article_id !== 0) {
  errors.push('article_id is missing');
}
if (!input.primary_keyword || String(input.primary_keyword).trim() === '') {
  errors.push('primary_keyword is missing or empty');
}

const validProviders = ['ollama', 'gemini', 'claude', 'chatgpt'];
if (!validProviders.includes(input.ai_provider)) {
  errors.push(`ai_provider "${input.ai_provider}" is not one of: ${validProviders.join(', ')}`);
}

const validAudiences = ['innovation_manager', 'c_level_exec'];
if (!validAudiences.includes(input.target_audience)) {
  errors.push(`target_audience "${input.target_audience}" is not one of: ${validAudiences.join(', ')}`);
}

if (errors.length > 0) {
  const articleIdForError = input.article_id ?? 'UNKNOWN';
  throw new Error(`[article_id=${articleIdForError}] Validation failed: ${errors.join('; ')}`);
}

const master = {
  article_id: input.article_id,
  primary_keyword: String(input.primary_keyword).trim(),
  format: input.format || null,
  ai_provider: input.ai_provider,
  target_audience: input.target_audience,
  other_notes: input.other_notes && input.other_notes !== '-' ? input.other_notes : '',

  pipeline_phase: '1_initialized',
  created_at: new Date().toISOString(),

  target_audience_document: null,
  serp_data: null,
  seo_brief: null,
  internal_links: null,
  selected_angle: null,
  outline_options: null,
  confirmed_outline: null,
  section_drafts: [],
  full_draft: null,
  audit_notes: null,
  output_doc_url: null,
  tokens_used: { input: 0, output: 0, thinking: 0 },

  errors: []
};

return { json: { master } };

const docResponse = $input.first().json;
const master = $('Initialization').first().json.master;

const personaText = (docResponse.content || '').trim();

if (!personaText) {
  throw new Error(
    `[article_id=${master.article_id}] Persona doc for target_audience="${master.target_audience}" is empty. Doc ID: ${docResponse.documentId || 'unknown'}`
  );
}

master.target_audience_document = personaText;
master.pipeline_phase = '2_persona_loaded';

return { json: { master } };

// Finalize SERP Data
// Extracts the parts of the SerpApi response that matter for SEO/GEO analysis
// and folds them into the master object.

const serpRaw = $input.first().json;
const master = $('Combine data 1').first().json.master;

// --- Helper: normalize an AI overview into a compact, consistent shape ---
function extractAiOverview(ao) {
  if (!ao) return null;
  return {
    text_blocks: (ao.text_blocks || []).map(b => ({
      type: b.type || null,
      snippet: b.snippet || null,
      list: b.list || null
    })),
    references: (ao.references || []).map(r => ({
      title: r.title || null,
      link: r.link || null,
      source: r.source || null,
      index: r.index ?? null
    }))
  };
}

// --- Top 10 organic results, trimmed ---
const organic = (serpRaw.organic_results || []).slice(0, 10).map(r => ({
  position: r.position,
  title: r.title,
  link: r.link,
  displayed_link: r.displayed_link,
  snippet: r.snippet,
  source: r.source || null,
  date: r.date || null
}));

// --- People Also Ask ---
const paa = (serpRaw.related_questions || []).map(q => ({
  question: q.question,
  snippet: q.snippet || null,
  link: q.link || null,
  list: q.list || null
}));

// --- Related searches ---
const relatedSearches = (serpRaw.related_searches || []).map(s => s.query);

// --- Main AI Overview (top of SERP) ---
const aiOverview = extractAiOverview(serpRaw.ai_overview);

// --- Topical AI Overviews nested inside knowledge_graph ---
// These are full AI Overviews for derivative queries like
// "what is the future of X", "what are the types of X", etc.
const topicalOverviews = {};
if (serpRaw.knowledge_graph) {
  for (const [key, node] of Object.entries(serpRaw.knowledge_graph)) {
    if (node && typeof node === 'object' && node.ai_overview) {
      topicalOverviews[key] = {
        link: node.link || null,
        ai_overview: extractAiOverview(node.ai_overview)
      };
    }
  }
}

// --- Inline videos ---
const inlineVideos = (serpRaw.inline_videos || []).map(v => ({
  position: v.position,
  title: v.title,
  link: v.link,
  channel: v.channel || null,
  duration: v.duration || null,
  date: v.date || null,
  snippet: v.snippet || null,
  platform: v.platform || null
}));

// --- Perspectives (social/editorial takes: LinkedIn, YouTube, Reddit, X, etc.) ---
const perspectives = (serpRaw.perspectives || []).map(p => ({
  author: p.author || null,
  author_description: p.author_description || null,
  source: p.source || null,
  title: p.title || null,
  snippet: p.snippet || null,
  link: p.link || null,
  date: p.date || null,
  engagement: Array.isArray(p.extensions) ? p.extensions.join(', ') : null
}));

// --- SERP features (presence flags) ---
const features = {
  ai_overview: !!aiOverview,
  topical_ai_overviews_count: Object.keys(topicalOverviews).length,
  featured_snippet: !!serpRaw.answer_box,
  answer_box: serpRaw.answer_box || null,
  knowledge_graph: !!serpRaw.knowledge_graph,
  inline_videos: inlineVideos.length > 0,
  inline_images: Array.isArray(serpRaw.inline_images) && serpRaw.inline_images.length > 0,
  top_stories: Array.isArray(serpRaw.top_stories) && serpRaw.top_stories.length > 0,
  shopping_results: Array.isArray(serpRaw.shopping_results) && serpRaw.shopping_results.length > 0,
  local_results: !!serpRaw.local_results,
  people_also_ask_present: paa.length > 0,
  related_searches_present: relatedSearches.length > 0,
  perspectives_present: perspectives.length > 0
};

// --- Store in master ---
master.serp_data = {
  query_used: serpRaw.search_parameters?.q || master.primary_keyword,
  search_metadata: {
    total_results: serpRaw.search_information?.total_results || null,
    time_taken: serpRaw.search_information?.time_taken_displayed || null,
    fetched_at: new Date().toISOString()
  },
  ai_overview: aiOverview,
  topical_ai_overviews: topicalOverviews,
  organic_results: organic,
  people_also_ask: paa,
  related_searches: relatedSearches,
  inline_videos: inlineVideos,
  perspectives: perspectives,
  serp_features: features
};

master.pipeline_phase = '3_serp_collected';

return { json: { master } };

const routerOutput = $input.first().json;
const master = $('Build AI Prompt').first().json._master;

master.seo_brief = routerOutput.response;
master.tokens_used.input += routerOutput.tokens_used.input;
master.tokens_used.output += routerOutput.tokens_used.output;
master.tokens_used.thinking += routerOutput.tokens_used.thinking;
master.pipeline_phase = '4_brief_generated';

return { json: { master } };

const master = $input.first().json.master;

const slug = master.primary_keyword
  .toLowerCase()
  .trim()
  .replace(/[^a-z0-9\s-]/g, '')
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .slice(0, 60);

master.article_folder_name = `${master.article_id}_${slug}`;

return { json: { master } };

const master = $('Slugify Keyword').first().json.master;
const articleFolder = $('Create Article Root Folder').first().json;

master.article_folder_url = `https://drive.google.com/drive/folders/${articleFolder.id}`;
master.article_folder_id = articleFolder.id;

return { json: { master } };
